from typing import *
from multiprocessing import Process
from fastapi import FastAPI
from fastapi.openapi.docs import (
    get_redoc_html,
    get_swagger_ui_html,
    get_swagger_ui_oauth2_redirect_html,
)
from fastapi.responses import JSONResponse, StreamingResponse
from fastapi.staticfiles import StaticFiles
from pydantic import BaseModel
import uvicorn
import matplotlib.pyplot as plt
import tempfile
import numpy as np
import os
import uuid

from core.util import load_model
from core.detection import get_plate
from core.ocr import get_ocr
from util.convert_image import b64_to_array


class DataModel(BaseModel):
    images: List[dict] = [
        {"image": ""},
        {"image": ""}
    ]


def start_ocr_serving(model_path="serving/wpod-net.json", api_host='0.0.0.0', api_port=8080, debug=True):
    wpod_net = load_model(model_path)
    app = FastAPI(docs_url=None, redoc_url=None, debug=debug)
    app.mount("/static", StaticFiles(directory="static"), name="static")

    @app.get("/docs", include_in_schema=False)
    async def custom_swagger_ui_html():
        return get_swagger_ui_html(
            openapi_url=app.openapi_url,
            title=app.title + " - Swagger UI",
            oauth2_redirect_url=app.swagger_ui_oauth2_redirect_url,
            swagger_js_url="/static/swagger-ui-bundle.js",
            swagger_css_url="/static/swagger-ui.css",
        )

    @app.get(app.swagger_ui_oauth2_redirect_url, include_in_schema=False)
    async def swagger_ui_redirect():
        return get_swagger_ui_oauth2_redirect_html()

    @app.get("/redoc", include_in_schema=False)
    async def redoc_html():
        return get_redoc_html(
            openapi_url=app.openapi_url,
            title=app.title + " - ReDoc",
            redoc_js_url="/static/redoc.standalone.js",
        )

    @app.post("/api/model/ocr")
    async def model_ocr(data: DataModel):
        with tempfile.TemporaryDirectory() as tmp_dir:
            print("Temporary Directory:", tmp_dir)
            response = []
            for d in data.images:
                image = b64_to_array(d['image'])
                print("Plate", image.shape)
                # image = np.array(d['image'])
                try:
                    image_path = os.path.join(tmp_dir, "{}.jpg".format(uuid.uuid4().hex))
                    plt.imsave(image_path, image)
                    LpImg, cor = get_plate(wpod_net, image_path)
                    plate_image_path = os.path.join(tmp_dir, "plate_{}".format(os.path.basename(image_path)))
                    plt.imsave(plate_image_path, LpImg[0])
                    LpText = get_ocr(plate_image_path)
                    response.append(LpText)
                except Exception as e:
                    print(e)

        content = {
            "response": response,
        }

        return JSONResponse(content=content, status_code=200)

    uvicorn.run(app, host=api_host, port=api_port)
